		masked[statusCol] = strings.Repeat("\x01", len([]rune(masked[statusCol])))
		maskLines[i] = "  " + strings.Join(masked, "\t")
	}
	mask := tabTableLines(header, maskLines)
	for _, line := range spliceColumnColor(plain, mask, colorize) {
		fmt.Fprintln(w, line)
	}
}

