730	// writeTabTable renders header + dataLines through a tabwriter with the trail
731	// list's column layout (2-space gutter). It is the single layout definition
732	// shared by the colored and uncolored paths.
733	func writeTabTable(w io.Writer, header string, dataLines []string) {
734		// tabwriter aligns by display columns (runes), so multi-byte branch names or
735		// logins don't throw off the table.
736		tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
737		fmt.Fprintln(tw, header)
738		for _, line := range dataLines {
739			fmt.Fprintln(tw, line)
740		}
741		_ = tw.Flush()
742	}
