744	// tabTableLines lays out the table and returns it split into lines (header
745	// first, then one line per data row), dropping the trailing empty line.
746	func tabTableLines(header string, dataLines []string) []string {
747		var b strings.Builder
748		writeTabTable(&b, header, dataLines)
749		lines := strings.Split(b.String(), "\n")
750		if n := len(lines); n > 0 && lines[n-1] == "" {
751			lines = lines[:n-1]
752		}
753		return lines
754	}
