756	// spliceColumnColor recolors one column on each line whose colorize entry is
757	// non-nil. The mask lines mark that column's span with sentinel bytes (0x01);
758	// because mask and plain share an identical layout, the sentinel's byte span in
759	// mask is the value's byte span in plain. colorize is indexed by data row;
760	// plain/mask carry the header at index 0, so data row i is line i+1.
761	func spliceColumnColor(plain, mask []string, colorize []func(string) string) []string {
762		out := append([]string(nil), plain...)
763		for i, fn := range colorize {
764			if fn == nil {
765				continue
766			}
767			line := i + 1
768			if line >= len(out) || line >= len(mask) {
769				continue
770			}
771			start := strings.IndexByte(mask[line], '\x01')
772			end := strings.LastIndexByte(mask[line], '\x01') + 1
773			if start < 0 || end <= start || end > len(out[line]) {
774				continue
775			}
776			out[line] = out[line][:start] + fn(out[line][start:end]) + out[line][end:]
777		}
778		return out
779	}
