18	// statusStyles holds pre-built lipgloss styles and terminal metadata.
19	type statusStyles struct {
20		colorEnabled bool
21		width        int
22	
23		// Styles
24		green   lipgloss.Style
25		red     lipgloss.Style
26		gray    lipgloss.Style
27		bold    lipgloss.Style
28		dim     lipgloss.Style
29		agent   lipgloss.Style // amber/orange for agent names
30		cyan    lipgloss.Style
31		yellow  lipgloss.Style // yellow for stale warnings
32		magenta lipgloss.Style
33	}
34	
35	// newStatusStyles creates styles appropriate for the output writer.
36	func newStatusStyles(w io.Writer) statusStyles {
37		useColor := shouldUseColor(w)
38		width := getTerminalWidth(w)
39	
40		s := statusStyles{
41			colorEnabled: useColor,
42			width:        width,
43		}
44	
45		if useColor {
46			s.green = lipgloss.NewStyle().Foreground(lipgloss.Color("2"))
47			s.red = lipgloss.NewStyle().Foreground(lipgloss.Color("1"))
48			s.gray = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))
49			s.bold = lipgloss.NewStyle().Bold(true)
50			s.dim = lipgloss.NewStyle().Faint(true)
51			s.agent = lipgloss.NewStyle().Bold(true).Foreground(lipgloss.Color("214"))
52			s.cyan = lipgloss.NewStyle().Foreground(lipgloss.Color("6"))
53			s.yellow = lipgloss.NewStyle().Foreground(lipgloss.Color("3"))
54			s.magenta = lipgloss.NewStyle().Foreground(lipgloss.Color("5"))
55		}
56	
57		return s
58	}
59	
60	// render applies a style to text only when color is enabled.
61	func (s statusStyles) render(style lipgloss.Style, text string) string {
62		if !s.colorEnabled {
63			return text
64		}
65		return style.Render(text)
66	}
67	
68	// shouldUseColor returns true if the writer supports color output.
69	func shouldUseColor(w io.Writer) bool {
70		return interactive.ShouldStyle(w)
71	}
72	
73	// getTerminalWidth returns the terminal width, capped at 80 with a fallback of 60.
74	// It first checks the writer itself, then falls back to Stdout/Stderr.
75	func getTerminalWidth(w io.Writer) int {
76		// Try the output writer first
77		if f, ok := w.(*os.File); ok {
78			if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
79				return min(width, 80)
80			}
81		}
82	
83		// Fall back to Stdout, then Stderr
84		for _, f := range []*os.File{os.Stdout, os.Stderr} {
85			if f == nil {
86				continue
87			}
88			if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
89				return min(width, 80)
90			}
91		}
92	
93		return 60
94	}
