96	// formatTokenCount formats a token count for display.
97	// 0 → "0", 500 → "500", 1200 → "1.2k", 14300 → "14.3k"
98	func formatTokenCount(n int) string {
99		if n < 1000 {
100			return strconv.Itoa(n)
101		}
102		f := float64(n) / 1000.0
103		s := fmt.Sprintf("%.1f", f)
104		// Remove trailing ".0" for clean display (e.g., 1000 → "1k" not "1.0k")
105		s = strings.TrimSuffix(s, ".0")
106		return s + "k"
107	}
108	
109	// totalTokens recursively sums all token fields including subagent tokens.
110	func totalTokens(tu *agent.TokenUsage) int {
111		if tu == nil {
112			return 0
113		}
114		total := saturatingIntAdd(tu.InputTokens, tu.CacheCreationTokens)
115		total = saturatingIntAdd(total, tu.CacheReadTokens)
116		total = saturatingIntAdd(total, tu.OutputTokens)
117		total = saturatingIntAdd(total, totalTokens(tu.SubagentTokens))
118		return total
119	}
