121	// explainRow is one entry in a metadata block: dim label + plain value.
122	type explainRow struct {
123		Label string
124		Value string
125	}
126	
127	// identityBullet renders "● <label> <id>\n". Bullet is brand orange when color
128	// is enabled; ID is also orange to mirror the existing checkpoint header. When
129	// id is empty (e.g., temporary checkpoints append "[temporary]" to the label
130	// instead of using an id slot), the trailing space + id is suppressed.
131	func (s statusStyles) identityBullet(label, id string) string {
132		if id == "" {
133			if !s.colorEnabled {
134				return fmt.Sprintf("● %s\n", label)
135			}
136			bullet := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), "●")
137			return fmt.Sprintf("%s %s\n", bullet, s.render(s.bold, label))
138		}
139		if !s.colorEnabled {
140			return fmt.Sprintf("● %s %s\n", label, id)
141		}
142		bullet := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), "●")
143		idStyled := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), id)
144		return fmt.Sprintf("%s %s %s\n", bullet, s.render(s.bold, label), idStyled)
145	}
146	
147	// listIdentityBullet renders "● <id>  <suffix>\n" — orange bullet, bold-orange ID,
148	// then plain (or dimmed) suffix. Used by the explain list view where the ID is
149	// the primary identifier (different ordering from identityBullet, which puts
150	// the static label first).
151	func (s statusStyles) listIdentityBullet(id, suffix string) string {
152		if !s.colorEnabled {
153			if suffix == "" {
154				return fmt.Sprintf("● %s\n", id)
155			}
156			return fmt.Sprintf("● %s  %s\n", id, suffix)
157		}
158		bullet := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")), "●")
159		idStyled := s.render(lipgloss.NewStyle().Foreground(lipgloss.Color("#fb923c")).Bold(true), id)
160		if suffix == "" {
161			return fmt.Sprintf("%s %s\n", bullet, idStyled)
162		}
163		return fmt.Sprintf("%s %s  %s\n", bullet, idStyled, suffix)
164	}
165	
166	// successBullet renders "✓ <label>\n" — green checkmark + bold label.
167	func (s statusStyles) successBullet(label string) string {
168		if !s.colorEnabled {
169			return fmt.Sprintf("✓ %s\n", label)
170		}
171		return fmt.Sprintf("%s %s\n", s.render(s.green, "✓"), s.render(s.bold, label))
172	}
173	
174	// failureBullet renders "✗ <label>\n" — red ✗ + bold label.
175	func (s statusStyles) failureBullet(label string) string {
176		if !s.colorEnabled {
177			return fmt.Sprintf("✗ %s\n", label)
178		}
179		return fmt.Sprintf("%s %s\n", s.render(s.red, "✗"), s.render(s.bold, label))
